import itertools
def lib(a):
    return {'a':a,'a2':a**2,'a3':a**3,'1/a':1/a,'1/a2':1/a**2,'sqrt':np.sqrt(a),'ln':np.log(a),'exp':np.exp(a),'expn':np.exp(-a),
            'sin':np.sin(a),'cos':np.cos(a),'tanh':np.tanh(a),'1':np.ones_like(a),'a1.5':a**1.5,'a4':a**4}
LX=lib(x); LV=lib(v)
PR={}
for fx,gx in LX.items():
    for fv,gv in LV.items():
        PR[(fx,fv)]=gx*gv
base=t*np.log(t)
keys=list(PR)
# precompute
res=[]
Ms={k:PR[k] for k in keys}
for a_,b_ in itertools.combinations(keys,2):
    A=np.column_stack([base,Ms[a_],Ms[b_]])
    c,_,_,_=np.linalg.lstsq(A,dv_dt,rcond=None)
    rr=np.mean((A@c-dv_dt)**2)/np.var(dv_dt)
    if rr<0.02: res.append((rr,a_,b_,np.round(c,4)))
res.sort(key=lambda z:z[0])
print(len(res))
for z in res[:10]: print(z)

from scipy.optimize import least_squares
base=t*np.log(t)
def mk(p):
    c0,c1,p1,q1,c2,p2=p
    return c0*base+c1*np.abs(x)**p1*np.abs(v)**q1+c2*np.abs(v)**p2
best=None
rng=np.random.default_rng(0)
for trial in range(300):
    p0=[-0.37,rng.normal()*3,rng.uniform(-2,3),rng.uniform(-2,3),rng.normal()*3,rng.uniform(-2,3)]
    try:
        s=least_squares(lambda p: mk(p)+ (0) - dv_dt, p0, max_nfev=2000)
        rr=np.mean(s.fun**2)/np.var(dv_dt)
        if best is None or rr<best[0]: best=(rr,s.x)
